import React, { Component } from "react";
import "./Homepage.css";

export default class Homepage extends Component {
  constructor(props) {
    super(props);
    this.state = {
      currentIndex: 0,
      homepage: null,
      images: []
    };
  }

  componentDidMount() {
    fetch("http://localhost:3001/pages/5", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(data => {
        // מניחים שהמבנה של המידע מתאים לטבלה שסופקה
        const images = [data.Img1, data.Img2, data.img3].filter(img => img !== null);
        this.setState({ homepage: data, images: images });
      });
  }

  render() {
    const { images } = this.state;

    return (
      <div className="homepage">
        <h1>גלריית דף הבית</h1>
        <div className="gallery">
          {images.map((image, index) => (
            <img key={index} src={image} alt={`תמונת גלריה ${index + 1}`} />
          ))}
        </div>
      </div>
    );
  }
}
